INSERT INTO T_ORDER VALUES (3, 30);
SAVEPOINT SP1;
UPDATE T_ORDER SET QTY = QTY + 5 WHERE ID <= 2;
SAVEPOINT SP2;
DELETE FROM T_ORDER WHERE ID = 1;
ROLLBACK TO SAVEPOINT SP1;
INSERT INTO T_ORDER VALUES (4, 40);
COMMIT;
SELECT COUNT(*) AS CNT, SUM(QTY) AS TOTAL FROM T_ORDER;

